// JxButton is the only library component used here — the rest is plain markup on the
// jx-* CSS contract, so nothing depends on component APIs I haven't confirmed.
import { useState, type FormEvent } from 'react';
import { JxButton } from '@jinx-ui/react';

export type RegistrationValues = {
  name: string;
  email: string;
  phone: string;
  country: string;
  city: string;
  street: string;
  zip: string;
};

type Field = {
  key: keyof RegistrationValues;
  label: string;
  type: string;
  autoComplete: string;
};

type Step = {
  title: string;
  fields: Field[];
};

const STEPS: Step[] = [
  {
    title: 'Контакты',
    fields: [
      { key: 'name', label: 'Имя и фамилия', type: 'text', autoComplete: 'name' },
      { key: 'email', label: 'Email', type: 'email', autoComplete: 'email' },
      { key: 'phone', label: 'Телефон', type: 'tel', autoComplete: 'tel' },
    ],
  },
  {
    title: 'Адрес',
    fields: [
      { key: 'country', label: 'Страна', type: 'text', autoComplete: 'country-name' },
      { key: 'city', label: 'Город', type: 'text', autoComplete: 'address-level2' },
      { key: 'street', label: 'Улица, дом, квартира', type: 'text', autoComplete: 'street-address' },
      { key: 'zip', label: 'Почтовый индекс', type: 'text', autoComplete: 'postal-code' },
    ],
  },
  { title: 'Проверка', fields: [] },
];

const EMPTY: RegistrationValues = {
  name: '',
  email: '',
  phone: '',
  country: '',
  city: '',
  street: '',
  zip: '',
};

const ALL_FIELDS = STEPS.flatMap((step) => step.fields);

export type RegistrationWizardProps = {
  onSubmit: (values: RegistrationValues) => void;
};

export default function RegistrationWizard({ onSubmit }: RegistrationWizardProps) {
  const [stepIndex, setStepIndex] = useState(0);
  const [values, setValues] = useState<RegistrationValues>(EMPTY);

  const step = STEPS[stepIndex];
  const isFirst = stepIndex === 0;
  const isLast = stepIndex === STEPS.length - 1;

  const setValue = (key: keyof RegistrationValues, next: string) =>
    setValues((prev) => ({ ...prev, [key]: next }));

  const handleSubmit = (event: FormEvent<HTMLFormElement>) => {
    event.preventDefault();
    if (isLast) {
      onSubmit(values);
      return;
    }
    setStepIndex((prev) => prev + 1);
  };

  return (
    <form
      className="jx-stack"
      onSubmit={handleSubmit}
      style={{ display: 'grid', gap: 'var(--jx-space-5, 20px)' }}
    >
      <ol
        className="jx-steps"
        aria-label="Шаги регистрации"
        style={{
          display: 'flex',
          gap: 'var(--jx-space-3, 12px)',
          listStyle: 'none',
          margin: 0,
          padding: 0,
        }}
      >
        {STEPS.map((item, index) => (
          <li
            key={item.title}
            className="jx-steps__item"
            aria-current={index === stepIndex ? 'step' : undefined}
            style={{
              display: 'flex',
              alignItems: 'center',
              gap: 'var(--jx-space-2, 8px)',
              color:
                index === stepIndex
                  ? 'var(--jx-color-text, inherit)'
                  : 'var(--jx-color-text-muted, inherit)',
            }}
          >
            <span className="jx-badge" aria-hidden="true">
              {index + 1}
            </span>
            <span>{item.title}</span>
          </li>
        ))}
      </ol>

      <fieldset
        className="jx-fieldset"
        style={{ border: 0, margin: 0, padding: 0, display: 'grid', gap: 'var(--jx-space-4, 16px)' }}
      >
        <legend className="jx-heading">{step.title}</legend>

        {step.fields.map((field) => (
          <div
            key={field.key}
            className="jx-field"
            style={{ display: 'grid', gap: 'var(--jx-space-2, 8px)' }}
          >
            <label className="jx-label" htmlFor={`reg-${field.key}`}>
              {field.label}
            </label>
            <input
              id={`reg-${field.key}`}
              className="jx-input"
              type={field.type}
              autoComplete={field.autoComplete}
              value={values[field.key]}
              onChange={(event) => setValue(field.key, event.target.value)}
            />
          </div>
        ))}

        {isLast && (
          <dl
            className="jx-list"
            style={{ display: 'grid', gap: 'var(--jx-space-2, 8px)', margin: 0 }}
          >
            {ALL_FIELDS.map((field) => (
              <div
                key={field.key}
                style={{ display: 'flex', justifyContent: 'space-between', gap: 'var(--jx-space-3, 12px)' }}
              >
                <dt className="jx-text-muted">{field.label}</dt>
                <dd style={{ margin: 0 }}>{values[field.key] || '—'}</dd>
              </div>
            ))}
          </dl>
        )}
      </fieldset>

      <div
        className="jx-actions"
        style={{ display: 'flex', gap: 'var(--jx-space-3, 12px)', justifyContent: 'flex-end' }}
      >
        <JxButton
          type="button"
          disabled={isFirst}
          onClick={() => setStepIndex((prev) => Math.max(0, prev - 1))}
        >
          Назад
        </JxButton>
        <JxButton type="submit" variant="primary">
          {isLast ? 'Отправить' : 'Дальше'}
        </JxButton>
      </div>
    </form>
  );
}

